class Gradebook:
    def __init__(self) -> None:
        # assignment name -> (weight, kind)
        self._assignments = {}
        # student -> {assignment name -> grade}
        self._grades = {}

    def add_assignment(self, name: str, weight: float, kind: str = "homework") -> None:
        """kind is "homework" or "quiz"."""
        if kind not in ("homework", "quiz"):
            raise ValueError('kind must be "homework" or "quiz"')
        self._assignments[name] = (weight, kind)

    def record(self, student: str, assignment: str, grade: float) -> None:
        if assignment not in self._assignments:
            raise KeyError(f"Unknown assignment: {assignment}")
        if not (2.0 <= grade <= 5.0):
            raise ValueError("Grade must be between 2.0 and 5.0")
        self._grades.setdefault(student, {})[assignment] = grade

    def average(self, student: str) -> float:
        student_grades = self._grades.get(student, {})

        # Gather quiz assignments the student has recorded, and find the lowest
        quiz_names = [
            name for name, (_, kind) in self._assignments.items()
            if kind == "quiz" and name in student_grades
        ]
        dropped_quiz = None
        if len(quiz_names) > 1:
            dropped_quiz = min(quiz_names, key=lambda n: student_grades[n])

        total_weight = 0.0
        weighted_sum = 0.0

        for name, (weight, _kind) in self._assignments.items():
            if name == dropped_quiz:
                continue
            grade = student_grades.get(name, 2.0)
            weighted_sum += weight * grade
            total_weight += weight

        if total_weight == 0:
            return 0.0

        return round(weighted_sum / total_weight, 2)
